  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const timeEl = document.getElementById("time");
    const hitsEl = document.getElementById("hits");
    const shotsEl = document.getElementById("shots");
    const stateEl = document.getElementById("state");
    const boardEl = document.getElementById("board");
    const emptyBoardEl = document.getElementById("emptyBoard");

    const startBtn = document.getElementById("startBtn");
    const resetBtn = document.getElementById("resetBtn");
    const clearBtn = document.getElementById("clearBtn");

    const modalMask = document.getElementById("modalMask");
    const finalTimeEl = document.getElementById("finalTime");
    const playerNameEl = document.getElementById("playerName");
    const saveScoreBtn = document.getElementById("saveScoreBtn");

    const W = canvas.width;
    const H = canvas.height;

    const bow = { x: 95, y: 390 };
    const gravity = 650;
    const maxPull = 170;
    const minShootPull = 15;

    let gameState = "idle";
    let startTime = 0;
    let finishTime = 0;
    let elapsed = 0;
    let shots = 0;
    let aiming = false;
    let aimPoint = { x: bow.x + 120, y: bow.y - 30 };
    let arrow = null;
    let lastFrame = performance.now();

    let targets = [];

    function createTargets() {
      return [
        { x: 745, y: 160, r: 38, hit: false },
        { x: 860, y: 245, r: 36, hit: false },
        { x: 705, y: 335, r: 34, hit: false },
        { x: 830, y: 420, r: 32, hit: false }
      ];
    }

    function resetGame(startImmediately = false) {
      targets = createTargets();
      shots = 0;
      elapsed = 0;
      finishTime = 0;
      arrow = null;
      aiming = false;
      aimPoint = { x: bow.x + 120, y: bow.y - 30 };
      gameState = startImmediately ? "playing" : "idle";
      if (startImmediately) startTime = performance.now();
      updateHUD();
    }

    function startGame() {
      resetGame(true);
    }

    function finishGame() {
      gameState = "finished";
      finishTime = elapsed;
      finalTimeEl.textContent = finishTime.toFixed(2) + "s";
      modalMask.style.display = "flex";
      playerNameEl.value = "";
      setTimeout(() => playerNameEl.focus(), 50);
      updateHUD();
    }

    function allTargetsHit() {
      return targets.every(t => t.hit);
    }

    function hitCount() {
      return targets.filter(t => t.hit).length;
    }

    function updateHUD() {
      timeEl.textContent = elapsed.toFixed(2) + "s";
      hitsEl.textContent = `${hitCount()} / 4`;
      shotsEl.textContent = shots;

      if (gameState === "idle") stateEl.textContent = "待开始";
      if (gameState === "playing") stateEl.textContent = "进行中";
      if (gameState === "finished") stateEl.textContent = "已完成";
    }

    function getMousePos(evt) {
      const rect = canvas.getBoundingClientRect();
      const clientX = evt.touches ? evt.touches[0].clientX : evt.clientX;
      const clientY = evt.touches ? evt.touches[0].clientY : evt.clientY;
      return {
        x: (clientX - rect.left) * W / rect.width,
        y: (clientY - rect.top) * H / rect.height
      };
    }

    function clampAimPoint(p) {
      let dx = p.x - bow.x;
      let dy = p.y - bow.y;
      const d = Math.hypot(dx, dy);
      if (d > maxPull) {
        dx = dx / d * maxPull;
        dy = dy / d * maxPull;
      }
      return { x: bow.x + dx, y: bow.y + dy };
    }

    function pointerDown(evt) {
      if (gameState !== "playing") return;
      evt.preventDefault();
      aiming = true;
      aimPoint = clampAimPoint(getMousePos(evt));
    }

    function pointerMove(evt) {
      if (!aiming || gameState !== "playing") return;
      evt.preventDefault();
      aimPoint = clampAimPoint(getMousePos(evt));
    }

    function pointerUp(evt) {
      if (!aiming || gameState !== "playing") return;
      evt.preventDefault();
      aiming = false;

      const dx = aimPoint.x - bow.x;
      const dy = aimPoint.y - bow.y;
      const pull = Math.hypot(dx, dy);

      if (pull < minShootPull) return;

      shots++;

      arrow = {
        x: bow.x,
        y: bow.y,
        vx: dx * 4.1,
        vy: dy * 4.1,
        angle: Math.atan2(dy, dx)
      };

      updateHUD();
    }

    canvas.addEventListener("mousedown", pointerDown);
    canvas.addEventListener("mousemove", pointerMove);
    window.addEventListener("mouseup", pointerUp);

    canvas.addEventListener("touchstart", pointerDown, { passive: false });
    canvas.addEventListener("touchmove", pointerMove, { passive: false });
    window.addEventListener("touchend", pointerUp, { passive: false });

    startBtn.addEventListener("click", startGame);
    resetBtn.addEventListener("click", () => resetGame(gameState === "playing"));
    clearBtn.addEventListener("click", () => {
      if (confirm("确定清空排行榜吗？")) {
        localStorage.removeItem("archeryLeaderboard");
        renderLeaderboard();
      }
    });

    saveScoreBtn.addEventListener("click", saveScore);

    playerNameEl.addEventListener("keydown", e => {
      if (e.key === "Enter") saveScore();
    });

    function saveScore() {
      const name = playerNameEl.value.trim() || "匿名玩家";
      const list = getLeaderboard();

      list.push({
        name,
        time: Number(finishTime.toFixed(2)),
        date: new Date().toLocaleString()
      });

      list.sort((a, b) => a.time - b.time);
      localStorage.setItem("archeryLeaderboard", JSON.stringify(list.slice(0, 10)));

      modalMask.style.display = "none";
      renderLeaderboard();
    }

    function getLeaderboard() {
      try {
        return JSON.parse(localStorage.getItem("archeryLeaderboard")) || [];
      } catch {
        return [];
      }
    }

    function renderLeaderboard() {
      const list = getLeaderboard();
      boardEl.innerHTML = "";

      emptyBoardEl.style.display = list.length ? "none" : "block";

      list.forEach(item => {
        const li = document.createElement("li");
        li.innerHTML = `<b>${escapeHtml(item.name)}</b> - ${item.time.toFixed(2)}s<br><small>${item.date}</small>`;
        boardEl.appendChild(li);
      });
    }

    function escapeHtml(str) {
      return str.replace(/[&<>"']/g, ch => ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#039;"
      }[ch]));
    }

    function update(dt) {
      if (gameState === "playing") {
        elapsed = (performance.now() - startTime) / 1000;
      }

      if (arrow && gameState === "playing") {
        arrow.x += arrow.vx * dt;
        arrow.y += arrow.vy * dt;
        arrow.vy += gravity * dt;
        arrow.angle = Math.atan2(arrow.vy, arrow.vx);

        for (const t of targets) {
          if (!t.hit) {
            const d = Math.hypot(arrow.x - t.x, arrow.y - t.y);
            if (d <= t.r) {
              t.hit = true;
              arrow = null;
              if (allTargetsHit()) finishGame();
              break;
            }
          }
        }

        if (arrow && (arrow.x > W + 80 || arrow.x < -80 || arrow.y > H + 80 || arrow.y < -120)) {
          arrow = null;
        }
      }

      updateHUD();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      drawScene();
      drawTargets();
      drawBow();

      if (aiming && gameState === "playing") {
        drawAimGuide();
      }

      if (arrow) {
        drawArrow(arrow.x, arrow.y, arrow.angle);
      }

      if (gameState === "idle") {
        drawCenterText("点击右侧“开始游戏”开始挑战");
      }

      if (gameState === "finished") {
        drawCenterText("挑战完成！");
      }
    }

    function drawScene() {
      ctx.fillStyle = "rgba(255,255,255,0.35)";
      drawCloud(160, 90, 1.1);
      drawCloud(450, 70, 0.9);

      ctx.fillStyle = "#6ebb54";
      ctx.fillRect(0, 350, W, H - 350);

      ctx.fillStyle = "#4b9c3d";
      for (let x = 0; x < W; x += 32) {
        ctx.beginPath();
        ctx.moveTo(x, H);
        ctx.lineTo(x + 12, 365);
        ctx.lineTo(x + 24, H);
        ctx.fill();
      }

      ctx.fillStyle = "#85562a";
      ctx.fillRect(55, 352, 80, 12);
    }

    function drawCloud(x, y, s) {
      ctx.beginPath();
      ctx.arc(x, y, 22 * s, 0, Math.PI * 2);
      ctx.arc(x + 24 * s, y - 10 * s, 28 * s, 0, Math.PI * 2);
      ctx.arc(x + 55 * s, y, 24 * s, 0, Math.PI * 2);
      ctx.arc(x + 28 * s, y + 12 * s, 24 * s, 0, Math.PI * 2);
      ctx.fill();
    }

    function drawTargets() {
      targets.forEach((t, i) => {
        ctx.save();

        ctx.strokeStyle = "#5b3a1c";
        ctx.lineWidth = 7;
        ctx.beginPath();
        ctx.moveTo(t.x, t.y + t.r);
        ctx.lineTo(t.x, H - 58);
        ctx.stroke();

        ctx.fillStyle = "#754c24";
        ctx.fillRect(t.x - 28, H - 62, 56, 12);

        ctx.translate(t.x, t.y);

        if (t.hit) {
          ctx.globalAlpha = 0.45;
        }

        const rings = [
          { r: t.r, c: "#f3f3f3" },
          { r: t.r * 0.78, c: "#e33b3b" },
          { r: t.r * 0.55, c: "#f3f3f3" },
          { r: t.r * 0.34, c: "#236bff" },
          { r: t.r * 0.16, c: "#ffd43b" }
        ];

        rings.forEach(ring => {
          ctx.beginPath();
          ctx.fillStyle = ring.c;
          ctx.arc(0, 0, ring.r, 0, Math.PI * 2);
          ctx.fill();
          ctx.strokeStyle = "rgba(0,0,0,0.25)";
          ctx.lineWidth = 1;
          ctx.stroke();
        });

        ctx.globalAlpha = 1;
        ctx.fillStyle = "#111";
        ctx.font = "bold 14px Arial";
        ctx.textAlign = "center";
        ctx.fillText(t.hit ? "命中" : String(i + 1), 0, -t.r - 10);

        ctx.restore();
      });
    }

    function drawBow() {
      ctx.save();
      ctx.translate(bow.x, bow.y);

      ctx.strokeStyle = "#5b2c06";
      ctx.lineWidth = 8;
      ctx.beginPath();
      ctx.arc(0, 0, 70, -Math.PI / 2, Math.PI / 2);
      ctx.stroke();

      ctx.strokeStyle = "#eee";
      ctx.lineWidth = 2;

      if (aiming && gameState === "playing") {
        ctx.beginPath();
        ctx.moveTo(0, -70);
        ctx.lineTo(aimPoint.x - bow.x, aimPoint.y - bow.y);
        ctx.lineTo(0, 70);
        ctx.stroke();

        drawArrow(aimPoint.x - bow.x, aimPoint.y - bow.y, Math.atan2(aimPoint.y - bow.y, aimPoint.x - bow.x), true);
      } else {
        ctx.beginPath();
        ctx.moveTo(0, -70);
        ctx.lineTo(0, 70);
        ctx.stroke();
      }

      ctx.fillStyle = "#2b1606";
      ctx.beginPath();
      ctx.arc(0, 0, 6, 0, Math.PI * 2);
      ctx.fill();

      ctx.restore();
    }

    function drawAimGuide() {
      const dx = aimPoint.x - bow.x;
      const dy = aimPoint.y - bow.y;
      const power = Math.min(Math.hypot(dx, dy) / maxPull, 1);

      ctx.strokeStyle = `rgba(35, 107, 255, ${0.25 + power * 0.5})`;
      ctx.setLineDash([8, 8]);
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(bow.x, bow.y);
      ctx.lineTo(aimPoint.x, aimPoint.y);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.fillStyle = "#111";
      ctx.font = "14px Arial";
      ctx.fillText(`力度：${Math.round(power * 100)}%`, bow.x + 12, bow.y - 92);
    }

    function drawArrow(x, y, angle, local = false) {
      ctx.save();

      if (!local) {
        ctx.translate(x, y);
      } else {
        ctx.translate(x, y);
      }

      ctx.rotate(angle);

      ctx.strokeStyle = "#3a2512";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(-28, 0);
      ctx.lineTo(22, 0);
      ctx.stroke();

      ctx.fillStyle = "#555";
      ctx.beginPath();
      ctx.moveTo(30, 0);
      ctx.lineTo(18, -6);
      ctx.lineTo(18, 6);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = "#d13b3b";
      ctx.beginPath();
      ctx.moveTo(-30, 0);
      ctx.lineTo(-44, -8);
      ctx.lineTo(-39, 0);
      ctx.lineTo(-44, 8);
      ctx.closePath();
      ctx.fill();

      ctx.restore();
    }

    function drawCenterText(text) {
      ctx.save();
      ctx.fillStyle = "rgba(0,0,0,0.52)";
      ctx.fillRect(0, 0, W, H);

      ctx.fillStyle = "white";
      ctx.font = "bold 34px Arial";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(text, W / 2, H / 2);

      ctx.restore();
    }

    function loop(now) {
      const dt = Math.min((now - lastFrame) / 1000, 0.033);
      lastFrame = now;
      update(dt);
      draw();
      requestAnimationFrame(loop);
    }

    resetGame(false);
    renderLeaderboard();
    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

## 运行方式

1. 新建文件：`index.html`
2. 将上面的完整代码复制进去并保存。
3. 使用浏览器打开 `index.html`。
4. 点击“开始游戏”。
5. 按住鼠标或手指拖动瞄准，松开射箭。
6. 命中全部四个靶子后输入名字，成绩会保存到本地排行榜。

## 测试说明

可按以下流程测试：

1. **基础启动测试**
   - 打开页面后应显示游戏画布、状态面板和排行榜。
   - 初始状态为“待开始”。

2. **开始游戏测试**
   - 点击“开始游戏”。
   - 计时器开始增长。
   - 状态变为“进行中”。

3. **射箭测试**
   - 在画布中按住并拖动。
   - 应显示瞄准线和力度。
   - 松开后箭会按抛物线飞出。

4. **命中测试**
   - 箭碰到靶子圆形区域后，该靶显示为“命中”。
   - 命中数增加。
   - 共四个靶子全部命中后游戏结束。

5. **排行榜测试**
   - 全部命中后弹出输入名字窗口。
   - 输入名字并保存。
   - 成绩会按完成时间从短到长排序。
   - 刷新页面后排行榜仍保留。

6. **清空排行榜测试**
   - 点击“清空排行榜”。
   - 确认后排行榜应变为空。

