    '<h2>全部命中！</h2>' +
    '<p>用时：<b>' + elapsed.toFixed(2) + 's</b>，共射出 ' + arrowCount + ' 支箭</p>' +
    '<p>排行榜名次：<b>第 ' + rank + ' 名</b></p>' +
    '<button id="againBtn">再来一局</button>';
  document.getElementById('againBtn').addEventListener('click', startGame);
}

function loadBoard() {
  try { return JSON.parse(localStorage.getItem(LB_KEY)) || []; }
  catch (e) { return []; }
}

function saveScore(time, arrows) {
  let name = prompt('恭喜完成！输入你的名字记入排行榜：', '神射手');
  if (name === null) name = '匿名';
  name = (name.trim() || '匿名').slice(0, 12);
  const board = loadBoard();
  const entry = { name, time: +time.toFixed(2), arrows, ts: Date.now() };
  board.push(entry);
  board.sort((a, b) => a.time - b.time);
  const top = board.slice(0, 10);
  localStorage.setItem(LB_KEY, JSON.stringify(top));
  window._lastEntry = entry;
  const idx = top.indexOf(entry);
  return idx >= 0 ? idx + 1 : '10+';
}

function renderBoard() {
  const board = loadBoard();
  if (!board.length) {
    boardBody.innerHTML = '<tr><td colspan="3" style="text-align:center;color:#889">暂无记录</td></tr>';
    return;
  }
  boardBody.innerHTML = board.map((e, i) => {
    const me = window._lastEntry && e.ts === window._lastEntry.ts ? ' class="me"' : '';
    return '<tr' + me + '><td>' + (i + 1) + '</td><td>' + escapeHtml(e.name) +
           '</td><td>' + e.time.toFixed(2) + 's</td></tr>';
  }).join('');
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
  }[c]));
}

function drawTarget(t) {
  const rings = [
    { r: t.r,       c: '#ffffff' },
    { r: t.r*0.75,  c: '#e33b3b' },
    { r: t.r*0.5,   c: '#ffffff' },
    { r: t.r*0.28,  c: '#f4c430' },
  ];
  for (const ring of rings) {
    ctx.beginPath();
    ctx.arc(t.x, t.y, ring.r, 0, Math.PI * 2);
    ctx.fillStyle = t.hit ? '#9fb89a' : ring.c;
    ctx.fill();
    ctx.lineWidth = 1.5;
    ctx.strokeStyle = '#555';
    ctx.stroke();
  }
  if (t.hit) {
    ctx.fillStyle = '#2b6b2b';
    ctx.font = 'bold 20px sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText('✓', t.x, t.y);
  }
}

function drawArcher() {
  ctx.fillStyle = '#5a3d2b';
  ctx.fillRect(ARCHER.x - 8, ARCHER.y, 16, H - ARCHER.y);
  ctx.strokeStyle = '#3a2a1a';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(ARCHER.x, ARCHER.y - 6, 22, -Math.PI/2.2, Math.PI/2.2);
  ctx.stroke();
}

function drawAimGuide() {
  if (!aiming || !aimStart || !aimNow) return;
  let dx = aimStart.x - aimNow.x;
  let dy = aimStart.y - aimNow.y;
  let dist = Math.min(Math.hypot(dx, dy), MAX_POWER);
  if (dist < 1) return;
  const angle = Math.atan2(dy, dx);
  const speed = dist * POWER_SCALE;
  let px = ARCHER.x, py = ARCHER.y;
  let vx = Math.cos(angle) * speed, vy = Math.sin(angle) * speed;
  const dt = 1/60;
  ctx.setLineDash([5, 6]);
  ctx.strokeStyle = 'rgba(30,30,30,0.6)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(px, py);
  for (let i = 0; i < 90; i++) {
    vy += GRAVITY * dt;
    px += vx * dt; py += vy * dt;
    ctx.lineTo(px, py);
    if (px > W || py > H) break;
  }
  ctx.stroke();
  ctx.setLineDash([]);

  const pct = dist / MAX_POWER;
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.fillRect(ARCHER.x - 12, ARCHER.y - 70, 8, 50);
  ctx.fillStyle = pct > 0.8 ? '#e33b3b' : '#f4c430';
  ctx.fillRect(ARCHER.x - 12, ARCHER.y - 20 - 50*pct, 8, 50*pct);
}

function drawArrow() {
  if (!arrow) return;
  ctx.save();
  ctx.translate(arrow.x, arrow.y);
  ctx.rotate(arrow.angle);
  ctx.strokeStyle = '#4a3010';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(-18, 0); ctx.lineTo(10, 0);
  ctx.stroke();
  ctx.fillStyle = '#333';
  ctx.beginPath();
  ctx.moveTo(16, 0); ctx.lineTo(8, -4); ctx.lineTo(8, 4);
  ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#c33';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-18, 0); ctx.lineTo(-22, -4);
  ctx.moveTo(-18, 0); ctx.lineTo(-22, 4);
  ctx.stroke();
  ctx.restore();
}

function render() {
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#fff2b0';
  ctx.beginPath(); ctx.arc(W - 60, 55, 30, 0, Math.PI*2); ctx.fill();
  for (const t of targets) drawTarget(t);
  drawArcher();
  drawAimGuide();
  drawArrow();
}

function loop(t) {
  const dt = Math.min((t - lastT) / 1000 || 0, 0.05);
  lastT = t;
  if (state === 'playing') {
    elapsed = (performance.now() - startTime) / 1000;
    timeEl.textContent = elapsed.toFixed(2);
    stepArrow(dt);
  }
  render();
  requestAnimationFrame(loop);
}

makeTargets();
renderBoard();
requestAnimationFrame(loop);

window.__game = {
  get state() { return state; },
  get targets() { return targets; },
  get hitCount() { return hitCount; },
  start: startGame,
  fire(vx, vy) {
    if (state !== 'playing' || arrow) return false;
    arrow = { x: ARCHER.x, y: ARCHER.y, vx, vy, angle: Math.atan2(vy, vx) };
    arrowCount++; updateHud(); return true;
  },
  hitAll() {
    for (const t of targets) { if (!t.hit) { t.hit = true; hitCount++; } }
    updateHud(); checkFinish();
  }
};
</script>
</body>
